from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

from Team_Phoenix_Library import phoenix_gyro_turn

# Set up.
right_drive = Motor(Port.F, Direction.CLOCKWISE)
left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_attachment = Motor(Port.E, Direction.CLOCKWISE)
left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(left_drive, right_drive, 62.4, 90)


# The main program starts here.
drive_base.use_gyro(True)
drive_base.settings(turn_rate=90)
drive_base.straight(605)
phoenix_gyro_turn(200, 60, 30, 90, 'right', drive_base)
left_attachment.run_angle(500, 400)
drive_base.straight(315)
phoenix_gyro_turn(-200, -60, -30, -90, 'left', drive_base)
drive_base.settings(straight_speed=50)
drive_base.straight(100)
right_attachment.run_angle(500, 3100)
drive_base.straight(-120)
drive_base.settings(straight_speed=400)
phoenix_gyro_turn(-200, -120, -30, -150, 'left', drive_base)
drive_base.settings(straight_speed=200)
drive_base.straight(-20)
left_attachment.run_angle(50, -180)
drive_base.settings(straight_speed=100)
drive_base.straight(600)
